def can_second_player_win(root, n, x):
 parts=[]
 def size(node):
  if node is None:return 0
  left=size(node.left);right=size(node.right)
  if node.val==x:parts.extend((left,right))
  return left+right+1
 size(root);parts.append(n-1-sum(parts));return max(parts)>n//2

